/* SWAP:BRAND_ASSET — HÂLÂ EKSİK OLANLAR
   On iki tam logo geldi; üç satır hâlâ eksik ve hiçbiri uydurulmuyor:

     Wise         — zip'te YOKTU. Elde yalnızca simge (`path`); hero şeridinde
                    ve ödeme matrisinde adı geçiyor. Şeritte bugün plaka +
                    simge + düz ad olarak çıkan TEK marka bu.
     Visa         — kart şeması; yalnızca matris/şema satırında, yani zaten
     Mastercard     simge yuvası. Lockup gerekmiyor, istenmesin de.
     Revolut      — matris/şema satırı, yalnızca simge.

   DÖRDÜNCÜ SATIR VARDI, ARTIK YOK: müşteri panelinin markası. Kayıt
   defterinde vektörü hiç olmadı ve şeritte lucide ikonuyla akıyordu. Müşteri
   adın siteden tamamen çıkmasını istedi ("iş ortağımız vb değil, sadece panel
   olarak kullanıyoruz, ekstra adını geçirmemize gereken bir durum yok"), o
   yüzden brand.ts · PARTNERS'tan da kalktı. LOGOSU İSTENMEYECEK: eksik
   sanılıp listeye geri yazılmasın.

   Gelen dosya için yapılacak: `wordmark: { viewBox, parts, body, src }`.
   `body` gözle değil ÖLÇÜYLE bulunur — dosyayı canvas'a basıp satır satır
   mürekkep profili çıkarmak yeterli: mürekkebin en yoğun satırının %22'sini
   ilk aşan satır versal tepesi, son aşan satır taban çizgisidir; descender
   bilerek dışarıda kalır, işaret yazıdan yüksekse bant işaretin sınırına
   genişler. `src` dosyanın nereden geldiğini ve hangi izinle kullanıldığını
   yazar. */

export type BrandKey = keyof typeof BRANDS;

export const isBrandKey = (k: string): k is BrandKey => k in BRANDS;

/** Tam logosu olan marka mı? Çağrı yerleri düzeni buna göre kurabilsin diye. */
export const hasWordmark = (k: BrandKey): boolean => (BRANDS[k] as Brand).wordmark !== undefined;

/* Sitede bazı listeler markayı anahtarla değil görünen adıyla taşıyor
   (PAY_MATRIX satırları gibi). Bu eşleme o listeleri yeniden yazmadan işaret
   basabilmek için; karşılığı olmayan ad (ör. "Yerel banka") null dönüyor ve
   çağıran taraf yalnızca metni basıyor. */
const BY_TITLE = new Map<string, BrandKey>(
  (Object.keys(BRANDS) as BrandKey[]).map((k) => [BRANDS[k].title.toLowerCase(), k]),
);

export function brandKeyForName(name: string): BrandKey | null {
  return BY_TITLE.get(name.trim().toLowerCase()) ?? null;
}
